func bgClassT(l, c int32, lowMax, highMin int) string {
	score := int(l) * int(c)
	switch {
	case score >= highMin:
		return "bg-red-500"
	case score > lowMax:
		return "bg-amber-400"
	default:
		return "bg-green-500"
	}
}

func ns5814BgClass(l, c int32) string {
	return bgClassT(l, c, 5, 12)
}

